using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using Microsoft.Win32;

namespace NeuralNetwork.UI;

/*
 * This code was generated by ChatGPT, I am not taking credit for it. (And either am I learning how to make a good UI)
 */

public partial class MainWindow : Window
{
    public enum NetworkMode
    {
        New,
        Load
    }

    /// <summary>
    /// The UI's current settings. The UI deliberately does not construct or train a network itself.
    /// </summary>
    public sealed record TrainingOptions(
        NetworkMode Mode,
        string ModelPath,
        int[] Layers,
        int Iterations,
        int Recycles,
        string Backend,
        int AcceleratorIndex,
        bool MultiThread);

    /// <summary>Raised when the user clicks Start. Subscribe to this to run your backend.</summary>
    public event Action<TrainingOptions>? StartRequested;

    /// <summary>Raised when the user clicks Stop while a run is active.</summary>
    public event Action? StopRequested;

    private readonly List<int> _layerSizes = [784, 16, 16, 10];
    private readonly List<LayerRow> _layerRows = [];
    private NetworkMode _mode = NetworkMode.New;
    private bool _isTraining;

    public MainWindow()
    {
        InitializeComponent();
        DataObject.AddPastingHandler(IterationsBox, OnIntegerPaste);
        DataObject.AddPastingHandler(RecyclesBox, OnIntegerPaste);
        RenderLayers();
        RefreshModeUI();
        RefreshBackendUI();
        BackendCombo.SelectionChanged += (_, _) => RefreshBackendUI();
    }

    /// <summary>Thread-safe UI update. Percent should be in the range 0..100.</summary>
    public void ReportProgress(double percent, string? status = null)
    {
        RunOnUiThread(() =>
        {
            var clamped = Math.Clamp(percent, 0d, 100d);
            TrainingProgress.Value = clamped;
            ProgressText.Text = $"{clamped:0}%";
            if (!string.IsNullOrWhiteSpace(status))
                ProgressStatusText.Text = status;
        });
    }

    /// <summary>Thread-safe metric update. Accuracy is expected as a fraction, e.g. 0.956.</summary>
    public void ReportMetrics(float accuracy, float loss, float learningRate)
    {
        RunOnUiThread(() =>
        {
            AccuracyText.Text = float.IsFinite(accuracy) ? $"{accuracy * 100f:0.00}%" : "—";
            LossText.Text = float.IsFinite(loss) ? loss.ToString("0.000000") : "—";
            LearningRateText.Text = float.IsFinite(learningRate) ? learningRate.ToString("0.#####") : "—";
        });
    }

    /// <summary>Call when training completes or stops normally to restore the Start button.</summary>
    public void MarkTrainingCompleted(string status = "Training complete")
    {
        RunOnUiThread(() =>
        {
            _isTraining = false;
            StartStopButton.Content = "▶  START TRAINING";
            StartStopButton.Style = (Style)FindResource("AccentButtonStyle");
            StatusText.Text = status;
            RunStateText.Text = "COMPLETE";
            RunStateText.Foreground = (Brush)FindResource("GreenBrush");
            ProgressStatusText.Text = status;
        });
    }

    /// <summary>
    /// Replace the placeholder device list with the names from Context.Devices.
    /// For example: window.SetAccelerators(context.Devices.Select(d => d.Name));
    /// </summary>
    public void SetAccelerators(IEnumerable<string> acceleratorNames, int selectedIndex = 0)
    {
        var names = acceleratorNames?.ToList() ?? [];
        if (names.Count == 0)
            names.Add("No devices found");

        RunOnUiThread(() =>
        {
            // WPF does not allow ItemsSource to coexist with items declared in XAML.
            AcceleratorCombo.ItemsSource = null;
            AcceleratorCombo.Items.Clear();
            AcceleratorCombo.ItemsSource = names;
            AcceleratorCombo.SelectedIndex = Math.Clamp(selectedIndex, 0, names.Count - 1);
        });
    }

    public TrainingOptions GetTrainingOptions()
    {
        SyncLayerSizesFromRows();
        return new TrainingOptions(
            Mode: _mode,
            ModelPath: ModelPathBox.Text.Trim(),
            Layers: _layerSizes.ToArray(),
            Iterations: ParseInteger(IterationsBox, 10, 1, 1_000_000),
            Recycles: ParseInteger(RecyclesBox, 1, 1, 1_000_000),
            Backend: SelectedBackendName(),
            AcceleratorIndex: Math.Max(0, AcceleratorCombo.SelectedIndex),
            MultiThread: MultiThreadCheck.IsChecked == true);
    }

    private void AddLayerButton_Click(object sender, RoutedEventArgs e)
    {
        SyncLayerSizesFromRows();
        if (_layerSizes.Count < 2)
            _layerSizes.Add(10);

        // Insert a new hidden layer immediately before the output layer.
        _layerSizes.Insert(_layerSizes.Count - 1, 16);
        RenderLayers();
    }

    private void ModeButton_Click(object sender, RoutedEventArgs e)
    {
        _mode = _mode == NetworkMode.New ? NetworkMode.Load : NetworkMode.New;
        ModelPathBox.Text = _mode == NetworkMode.New ? "save.nn" : string.Empty;
        RefreshModeUI();
    }

    private void BrowseButton_Click(object sender, RoutedEventArgs e)
    {
        if (_mode == NetworkMode.New)
        {
            var dialog = new SaveFileDialog
            {
                Title = "Choose where to save the network",
                Filter = "Neural network files (*.nn)|*.nn|All files (*.*)|*.*",
                DefaultExt = ".nn",
                AddExtension = true,
                FileName = string.IsNullOrWhiteSpace(ModelPathBox.Text) ? "save.nn" : ModelPathBox.Text.Trim()
            };

            if (dialog.ShowDialog(this) == true)
                ModelPathBox.Text = dialog.FileName;
        }
        else
        {
            var dialog = new OpenFileDialog
            {
                Title = "Choose a network to load",
                Filter = "Neural network files (*.nn)|*.nn|All files (*.*)|*.*",
                CheckFileExists = true,
                Multiselect = false
            };

            if (dialog.ShowDialog(this) == true)
                ModelPathBox.Text = dialog.FileName;
        }
    }

    private void StartStopButton_Click(object sender, RoutedEventArgs e)
    {
        if (_isTraining)
        {
            StopRequested?.Invoke();
            _isTraining = false;
            StartStopButton.Content = "▶  START TRAINING";
            StartStopButton.Style = (Style)FindResource("AccentButtonStyle");
            StatusText.Text = "Stop requested";
            RunStateText.Text = "STOPPING";
            RunStateText.Foreground = (Brush)FindResource("DangerBrush");
            ProgressStatusText.Text = "Stop requested; waiting for the trainer to stop safely.";
            return;
        }

        var options = GetTrainingOptions();
        if (string.IsNullOrWhiteSpace(options.ModelPath))
        {
            MessageBox.Show(this,
                _mode == NetworkMode.New
                    ? "Choose a path for the network save file first."
                    : "Choose a network file to load first.",
                "Network file required", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        _isTraining = true;
        TrainingProgress.Value = 0;
        ProgressText.Text = "0%";
        ProgressStatusText.Text = "Training run requested";
        StatusText.Text = "Training requested";
        RunStateText.Text = "RUNNING";
        RunStateText.Foreground = (Brush)FindResource("AccentBrush");
        StartStopButton.Content = "■  STOP TRAINING";
        StartStopButton.Style = (Style)FindResource("DangerButtonStyle");
        StartRequested?.Invoke(options);
    }

    private void IterationsUp_Click(object sender, RoutedEventArgs e) => NudgeIntegerBox(IterationsBox, +1);
    private void IterationsDown_Click(object sender, RoutedEventArgs e) => NudgeIntegerBox(IterationsBox, -1);
    private void RecyclesUp_Click(object sender, RoutedEventArgs e) => NudgeIntegerBox(RecyclesBox, +1);
    private void RecyclesDown_Click(object sender, RoutedEventArgs e) => NudgeIntegerBox(RecyclesBox, -1);

    private void DigitsOnly_PreviewTextInput(object sender, TextCompositionEventArgs e)
    {
        e.Handled = !Regex.IsMatch(e.Text, "^[0-9]+$");
    }

    private void RefreshModeUI()
    {
        var isNew = _mode == NetworkMode.New;
        ModeButton.Content = isNew ? "MODE: NEW" : "MODE: LOAD";
        PathLabel.Text = isNew ? "SAVE NETWORK TO" : "LOAD NETWORK FROM";
        BrowseButton.Content = isNew ? "Save as…" : "Browse…";
        LayerEditorPanel.IsEnabled = isNew;
        LayerEditorPanel.Opacity = isNew ? 1.0 : 0.42;
        LayersScrollViewer.IsEnabled = isNew;
        LayersScrollViewer.Opacity = isNew ? 1.0 : 0.42;
        LayerModeHint.Text = isNew
            ? "New network mode · add hidden layers before the output layer."
            : "Load mode · layer structure is controlled by the loaded network.";
        ModeButton.ToolTip = isNew
            ? "Currently creating a new network. Click to switch to Load mode."
            : "Currently loading an existing network. Click to switch to New mode.";
    }

    private void RefreshBackendUI()
    {
        var backend = SelectedBackendName();
        var isGpu = backend.Contains("GPU", StringComparison.OrdinalIgnoreCase);
        AcceleratorCombo.IsEnabled = isGpu;
        AcceleratorCombo.Opacity = isGpu ? 1.0 : 0.45;
    }

    private string SelectedBackendName()
    {
        if (BackendCombo.SelectedItem is ComboBoxItem item)
            return item.Content?.ToString() ?? "GPU (CUDA)";
        return BackendCombo.SelectedItem?.ToString() ?? "GPU (CUDA)";
    }

    private void RenderLayers()
    {
        LayersPanel.Children.Clear();
        _layerRows.Clear();

        for (var i = 0; i < _layerSizes.Count; i++)
        {
            var index = i;
            var isInput = index == 0;
            var isOutput = index == _layerSizes.Count - 1;
            var role = isInput ? "INPUT LAYER" : isOutput ? "OUTPUT LAYER" : $"HIDDEN LAYER {index}";
            var description = isInput ? "Input features" : isOutput ? "Output classes" : "Neurons in this layer";

            var rowBorder = new Border
            {
                Background = (Brush)FindResource("PanelRaisedBrush"),
                BorderBrush = (Brush)FindResource("PanelBorderBrush"),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(9),
                Padding = new Thickness(12),
                Margin = new Thickness(0, 0, 0, 8)
            };

            var rowGrid = new Grid { VerticalAlignment = VerticalAlignment.Center };
            rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(101) });
            rowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(33) });

            var labels = new StackPanel { VerticalAlignment = VerticalAlignment.Center };
            labels.Children.Add(new TextBlock
            {
                Text = role,
                FontSize = 10,
                FontWeight = FontWeights.Bold,
                Foreground = isInput || isOutput ? (Brush)FindResource("AccentBrush") : (Brush)FindResource("TextPrimaryBrush")
            });
            labels.Children.Add(new TextBlock
            {
                Text = description,
                FontSize = 11,
                Foreground = (Brush)FindResource("TextSecondaryBrush"),
                Margin = new Thickness(0, 4, 0, 0)
            });
            Grid.SetColumn(labels, 0);
            rowGrid.Children.Add(labels);

            var sizeGrid = new Grid { Height = 38 };
            sizeGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            sizeGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(23) });
            var sizeBox = new TextBox
            {
                Text = _layerSizes[index].ToString(),
                Height = 38,
                HorizontalContentAlignment = HorizontalAlignment.Center,
                VerticalContentAlignment = VerticalAlignment.Center,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 3, 0),
                ToolTip = "Number of neurons / features in this layer"
            };
            sizeBox.PreviewTextInput += DigitsOnly_PreviewTextInput;
            DataObject.AddPastingHandler(sizeBox, OnIntegerPaste);
            sizeGrid.Children.Add(sizeBox);

            var arrows = new StackPanel();// { Grid.Column = 1, VerticalAlignment = VerticalAlignment.Center };
            var upButton = new Button { Content = "▲", Style = (Style)FindResource("StepperButtonStyle"), ToolTip = "Increase layer size" };
            var downButton = new Button { Content = "▼", Style = (Style)FindResource("StepperButtonStyle"), ToolTip = "Decrease layer size" };
            upButton.Click += (_, _) => NudgeLayerSize(index, +1);
            downButton.Click += (_, _) => NudgeLayerSize(index, -1);
            arrows.Children.Add(upButton);
            arrows.Children.Add(downButton);
            Grid.SetColumn(arrows, 1);
            sizeGrid.Children.Add(arrows);
            Grid.SetColumn(sizeGrid, 1);
            rowGrid.Children.Add(sizeGrid);

            var removeButton = new Button
            {
                Content = "×",
                Width = 29,
                Height = 32,
                Padding = new Thickness(0),
                FontSize = 18,
                Foreground = (Brush)FindResource("TextSecondaryBrush"),
                Background = Brushes.Transparent,
                BorderBrush = Brushes.Transparent,
                IsEnabled = !isInput && !isOutput,
                ToolTip = isInput || isOutput ? "Input and output layers cannot be removed" : "Remove this hidden layer"
            };
            removeButton.Click += (_, _) => RemoveLayer(index);
            Grid.SetColumn(removeButton, 2);
            rowGrid.Children.Add(removeButton);

            rowBorder.Child = rowGrid;
            LayersPanel.Children.Add(rowBorder);
            _layerRows.Add(new LayerRow(sizeBox, removeButton));
        }

        AddLayerButton.IsEnabled = _mode == NetworkMode.New && _layerSizes.Count < 32;
        AddLayerButton.ToolTip = _layerSizes.Count >= 32 ? "Maximum of 32 layers in this UI" : "Add a hidden layer before the output layer";
    }

    private void RemoveLayer(int index)
    {
        if (_mode != NetworkMode.New || index <= 0 || index >= _layerSizes.Count - 1)
            return;

        SyncLayerSizesFromRows();
        _layerSizes.RemoveAt(index);
        RenderLayers();
    }

    private void NudgeLayerSize(int index, int delta)
    {
        if (_mode != NetworkMode.New || index < 0 || index >= _layerRows.Count)
            return;

        var box = _layerRows[index].SizeBox;
        var current = ParseInteger(box, _layerSizes[index], 1, 65_536);
        var next = Math.Clamp((long)current + delta, 1L, 65_536L);
        box.Text = next.ToString();
        box.CaretIndex = box.Text.Length;
        _layerSizes[index] = (int)next;
    }

    private void SyncLayerSizesFromRows()
    {
        for (var i = 0; i < _layerRows.Count && i < _layerSizes.Count; i++)
            _layerSizes[i] = ParseInteger(_layerRows[i].SizeBox, _layerSizes[i], 1, 65_536);
    }

    private static int ParseInteger(TextBox box, int fallback, int minimum, int maximum)
    {
        if (!int.TryParse(box.Text, out var value))
            value = fallback;
        value = Math.Clamp(value, minimum, maximum);
        box.Text = value.ToString();
        return value;
    }

    private static void NudgeIntegerBox(TextBox box, int delta)
    {
        var current = ParseInteger(box, 1, 1, 1_000_000);
        var next = Math.Clamp((long)current + delta, 1L, 1_000_000L);
        box.Text = next.ToString();
        box.CaretIndex = box.Text.Length;
    }

    private static void OnIntegerPaste(object sender, DataObjectPastingEventArgs e)
    {
        if (!e.DataObject.GetDataPresent(typeof(string)))
        {
            e.CancelCommand();
            return;
        }

        var text = e.DataObject.GetData(typeof(string)) as string;
        if (string.IsNullOrEmpty(text) || !Regex.IsMatch(text, "^[0-9]+$"))
            e.CancelCommand();
    }

    private void RunOnUiThread(Action action)
    {
        if (Dispatcher.CheckAccess())
            action();
        else
            Dispatcher.InvokeAsync(action);
    }

    private sealed record LayerRow(TextBox SizeBox, Button RemoveButton);
}
